args.new_string:
import { getPosts } from "../lib/api";
import { cacheLife } from "next/cache";
import { cacheTag } from "next/cache";

export default async function Home() {
  "use cache";
  cacheLife("posts");
  cacheTag("posts");

  const posts = await getPosts();

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>By {post.author}</p>
          </li>
        ))}
      </ul>
    </main>
  );
}

